"""Subscription push: match entity change events against a subscription.

Compiles a subscription operation into an equality filter plus a leaf-field
projection over a single @entity root, then applies it to an NDJSON stream of
entity change events. GraphQL, variable and @entity mapping semantics are
shared with the query planner; only the supported selection shape is narrower
(root entity scalar/enum leaf fields only).
"""

from __future__ import annotations

import json
from typing import Any, Dict, List, Optional, Tuple

from .errors import PlanError
from .gql import parse_executable
from .planner import Planner
from .schema import named_of

EVENT_OPS = ("INSERT", "UPDATE", "DELETE")


class SubscriptionPlan:
    """A compiled subscription ready to filter and project event snapshots."""

    __slots__ = ("operation_name", "path", "entity_table", "filter", "projections")

    def __init__(
        self,
        operation_name: Optional[str],
        path: str,
        entity_table: str,
        filter_obj: Dict[str, Any],
        projections: List[Tuple[str, str]],
    ):
        self.operation_name = operation_name
        self.path = path
        self.entity_table = entity_table
        self.filter = filter_obj  # entity field name -> expected value
        self.projections = projections  # (response key, entity field name) pairs

    def matches(self, snapshot: Dict[str, Any]) -> bool:
        for name, expected in self.filter.items():
            if name not in snapshot:
                raise PlanError(
                    "EventError", f"snapshot is missing filter field '{name}'"
                )
            if snapshot[name] != expected:
                return False
        return True

    def project(self, snapshot: Dict[str, Any]) -> Dict[str, Any]:
        data: Dict[str, Any] = {}
        for key, field_name in self.projections:
            if field_name not in snapshot:
                raise PlanError(
                    "EventError", f"snapshot is missing field '{field_name}'"
                )
            data[key] = snapshot[field_name]
        return data


class SubscriptionCompiler(Planner):
    """Reuses the planner's fragment expansion and variable resolution."""

    def compile(
        self, subscription_text: str, source: str, operation_name: Optional[str]
    ) -> SubscriptionPlan:
        operations, self.fragments = parse_executable(subscription_text, source)
        op = self._select_operation(operations, operation_name)
        self.var_map = {}
        for name, type_ref, default, has_default in op.var_defs:
            if name in self.var_map:
                raise PlanError(
                    "VariablesError", f"variable '${name}' is declared more than once"
                )
            self.var_map[name] = (type_ref, default, has_default)

        root_type_name = self.schema.roots.get("subscription")
        root_type = self.schema.types.get(root_type_name) if root_type_name else None
        if root_type is None:
            raise PlanError(
                "MappingError",
                "schema does not define a root type for subscription operations",
            )

        selections = self._expand(op.selection_set, root_type.name, [])
        if not selections:
            raise PlanError("InvalidQuery", "subscription has an empty selection set")
        if len(selections) != 1:
            raise PlanError(
                "InvalidQuery", "subscription must select exactly one root field"
            )
        node = selections[0]
        key = node.alias or node.name

        field = root_type.fields.get(node.name)
        if field is None:
            raise PlanError(
                "InvalidQuery",
                f"unknown root field '{node.name}' on type '{root_type.name}'",
            )
        type_name = named_of(field.type_ref)
        target = self.schema.types.get(type_name)
        entity = target.entity if target is not None else None
        if entity is None:
            raise PlanError(
                "MappingError",
                f"root field '{node.name}' does not return a mapped entity type",
            )
        if node.selection_set is None:
            raise PlanError(
                "InvalidQuery", f"root field '{node.name}' requires a selection set"
            )

        filter_obj = self._compile_filter(field, target, entity.table, node)
        projections = self._compile_projection(target, node.selection_set, key)
        return SubscriptionPlan(op.name, key, entity.table, filter_obj, projections)

    # -- operation selection ---------------------------------------------------

    @staticmethod
    def _select_operation(operations, operation_name):
        if operation_name is not None:
            for op in operations:
                if op.name == operation_name and op.op_type == "subscription":
                    return op
            raise PlanError(
                "InvalidQuery", f"no subscription named '{operation_name}'"
            )
        if not operations:
            raise PlanError("InvalidQuery", "document contains no operations")
        if len(operations) != 1:
            raise PlanError(
                "InvalidQuery",
                "multiple operations found; select one with --operation",
            )
        op = operations[0]
        if op.op_type != "subscription":
            raise PlanError("InvalidQuery", "operation must be a subscription")
        return op

    # -- filter ------------------------------------------------------------------

    def _compile_filter(self, field, target, table, node) -> Dict[str, Any]:
        for arg_name, arg_def in field.args.items():
            if (
                arg_def.type[0] == "non_null"
                and not arg_def.has_default
                and arg_name not in node.args
            ):
                raise PlanError(
                    "InvalidQuery",
                    f"missing required argument '{arg_name}' on root field '{node.name}'",
                )
        filter_obj: Dict[str, Any] = {}
        for arg_name, value in node.args.items():
            if arg_name not in field.args:
                raise PlanError(
                    "InvalidQuery",
                    f"unknown argument '{arg_name}' on root field '{node.name}'",
                )
            target_field = target.fields.get(arg_name)
            if target_field is None or not self.schema.is_leaf(
                named_of(target_field.type_ref)
            ):
                raise PlanError(
                    "InvalidQuery",
                    f"argument '{arg_name}' does not match a filterable field of entity '{table}'",
                )
            filter_obj[arg_name] = self._resolve(value)
        return filter_obj

    # -- projection ---------------------------------------------------------------

    def _compile_projection(
        self, target, selection_set, path: str
    ) -> List[Tuple[str, str]]:
        projections: List[Tuple[str, str]] = []
        seen = set()
        for node in self._expand(selection_set, target.name, []):
            key = node.alias or node.name
            field = target.fields.get(node.name)
            if field is None:
                raise PlanError(
                    "InvalidQuery",
                    f"unknown field '{node.name}' on type '{target.name}'",
                )
            if not self.schema.is_leaf(named_of(field.type_ref)):
                raise PlanError(
                    "UnsupportedSelection",
                    f"nested field '{node.name}' is not supported in subscriptions",
                )
            if node.selection_set is not None:
                raise PlanError(
                    "InvalidQuery",
                    f"scalar field '{node.name}' must not have a selection set",
                )
            if node.args:
                raise PlanError(
                    "InvalidQuery",
                    f"arguments on field '{node.name}' are not supported",
                )
            if key not in seen:
                seen.add(key)
                projections.append((key, node.name))
        if not projections:
            raise PlanError("InvalidQuery", f"empty selection set at '{path}'")
        return projections


def push_events(
    plan: SubscriptionPlan, events_text: str, source: str
) -> List[Dict[str, Any]]:
    """Apply a compiled subscription to an NDJSON event stream, in order."""
    outputs: List[Dict[str, Any]] = []
    for lineno, raw in enumerate(events_text.splitlines(), 1):
        line = raw.strip()
        if not line:
            continue
        event = _parse_event(line, source, lineno)
        if event["entity"] != plan.entity_table:
            continue
        op = event["op"]
        snapshot = event["after"] if op in ("INSERT", "UPDATE") else event["before"]
        if snapshot is None:
            raise PlanError(
                "EventError", f"{source}:{lineno}: {op} event has no snapshot"
            )
        if not plan.matches(snapshot):
            continue
        outputs.append(
            {
                "subscription": plan.operation_name,
                "path": plan.path,
                "event": op,
                "entity": event["entity"],
                "data": plan.project(snapshot),
            }
        )
    return outputs


def _parse_event(line: str, source: str, lineno: int) -> Dict[str, Any]:
    try:
        event = json.loads(line)
    except json.JSONDecodeError as exc:
        raise PlanError("EventError", f"{source}:{lineno}: invalid JSON: {exc.msg}")
    if not isinstance(event, dict):
        raise PlanError("EventError", f"{source}:{lineno}: event must be a JSON object")
    for key in ("op", "entity", "before", "after"):
        if key not in event:
            raise PlanError(
                "EventError", f"{source}:{lineno}: event is missing '{key}'"
            )
    if event["op"] not in EVENT_OPS:
        raise PlanError(
            "EventError", f"{source}:{lineno}: unknown op {event['op']!r}"
        )
    if not isinstance(event["entity"], str):
        raise PlanError(
            "EventError", f"{source}:{lineno}: 'entity' must be a string"
        )
    for key in ("before", "after"):
        if event[key] is not None and not isinstance(event[key], dict):
            raise PlanError(
                "EventError", f"{source}:{lineno}: '{key}' must be an object or null"
            )
    return event

"""Query plan builder.

Turns an executable GraphQL document plus resolved variables into a scan/join
plan over the entities declared in the schema. All validation failures raise
PlanError with the appropriate code; no partial plan is produced.
"""

from __future__ import annotations

from typing import Any, Dict, List, Optional

from .errors import PlanError
from .gql import (
    FieldNode,
    FragmentSpread,
    InlineFragment,
    Var,
    parse_executable,
)
from .schema import Schema, TypeInfo, named_of


class Planner:
    def __init__(self, schema: Schema, variables: Dict[str, Any]):
        self.schema = schema
        self.variables = variables
        self.fragments: Dict[str, Any] = {}
        self.var_map: Dict[str, tuple] = {}
        self.joins: List[dict] = []

    # -- entry point ---------------------------------------------------------

    def plan(self, query_text: str, source: str, operation_name: Optional[str]) -> dict:
        operations, self.fragments = parse_executable(query_text, source)
        op = self._select_operation(operations, operation_name)
        self.var_map = {}
        for name, type_ref, default, has_default in op.var_defs:
            if name in self.var_map:
                raise PlanError("VariablesError", f"variable '${name}' is declared more than once")
            self.var_map[name] = (type_ref, default, has_default)

        root_type_name = self.schema.roots.get(op.op_type)
        root_type = self.schema.types.get(root_type_name) if root_type_name else None
        if root_type is None:
            raise PlanError(
                "UnknownField",
                f"schema does not define a root type for {op.op_type} operations",
            )

        selections = self._expand(op.selection_set, root_type.name, [])
        if not selections:
            raise PlanError("InvalidQuery", "operation has an empty selection set")

        plan = {
            "operationType": op.op_type,
            "operationName": op.name,
            "roots": [],
            "joins": self.joins,
        }
        for node in selections:
            plan["roots"].append(self._plan_root(node, root_type))
        return plan

    # -- operation selection ---------------------------------------------------

    @staticmethod
    def _select_operation(operations, operation_name):
        if operation_name is not None:
            for op in operations:
                if op.name == operation_name:
                    if op.op_type == "subscription":
                        raise PlanError(
                            "UnsupportedOperation",
                            "subscription operations are not supported",
                        )
                    return op
            raise PlanError("InvalidOperation", f"no operation named '{operation_name}'")
        candidates = [op for op in operations if op.op_type in ("query", "mutation")]
        if len(candidates) == 1:
            return candidates[0]
        if not operations:
            raise PlanError("InvalidRequest", "document contains no operations")
        if not candidates and len(operations) == 1:
            raise PlanError(
                "UnsupportedOperation", "subscription operations are not supported"
            )
        raise PlanError(
            "InvalidRequest",
            "multiple operations found; select one with --operation",
        )

    # -- fragment expansion ------------------------------------------------------

    def _type_condition_matches(self, condition: str, type_name: str) -> bool:
        if condition == type_name:
            return True
        info = self.schema.types.get(type_name)
        if info is not None and condition in info.interfaces:
            return True
        members = self.schema.unions.get(condition)
        return bool(members) and type_name in members

    def _expand(self, selections, type_name: str, stack: List[str]) -> List[FieldNode]:
        """Inline fragments and merge fields by response key, preserving order."""
        out: List[FieldNode] = []
        index: Dict[str, FieldNode] = {}

        def add(node: FieldNode) -> None:
            key = node.alias or node.name
            existing = index.get(key)
            if existing is None:
                index[key] = FieldNode(
                    node.name,
                    node.alias,
                    dict(node.args),
                    list(node.selection_set) if node.selection_set is not None else None,
                )
                out.append(index[key])
                return
            if existing.name != node.name:
                raise PlanError(
                    "InvalidQuery",
                    f"conflicting fields '{existing.name}' and '{node.name}' share response key '{key}'",
                )
            if (existing.selection_set is None) != (node.selection_set is None):
                raise PlanError(
                    "InvalidQuery", f"conflicting selections for response key '{key}'"
                )
            if existing.selection_set is not None:
                existing.selection_set.extend(node.selection_set)

        for sel in selections:
            if isinstance(sel, FieldNode):
                add(sel)
            elif isinstance(sel, FragmentSpread):
                frag = self.fragments.get(sel.name)
                if frag is None:
                    raise PlanError("InvalidQuery", f"unknown fragment '{sel.name}'")
                if sel.name in stack:
                    raise PlanError(
                        "InvalidQuery", f"fragment cycle involving '{sel.name}'"
                    )
                if self._type_condition_matches(frag.type_condition, type_name):
                    for node in self._expand(frag.selection_set, type_name, stack + [sel.name]):
                        add(node)
            elif isinstance(sel, InlineFragment):
                if sel.type_condition is None or self._type_condition_matches(
                    sel.type_condition, type_name
                ):
                    for node in self._expand(sel.selection_set, type_name, stack):
                        add(node)
        return out

    # -- variables ------------------------------------------------------------

    def _resolve(self, value: Any) -> Any:
        if isinstance(value, Var):
            name = value.name
            if name not in self.var_map:
                raise PlanError(
                    "VariablesError", f"variable '${name}' is not declared by the operation"
                )
            type_ref, default, has_default = self.var_map[name]
            if name in self.variables:
                provided = self.variables[name]
                if not self._check_type(type_ref, provided):
                    raise PlanError(
                        "VariablesError",
                        f"variable '${name}' has a value of the wrong type",
                    )
                return provided
            if has_default:
                return default
            raise PlanError("VariablesError", f"variable '${name}' was not provided")
        if isinstance(value, list):
            return [self._resolve(item) for item in value]
        if isinstance(value, dict):
            return {key: self._resolve(item) for key, item in value.items()}
        return value

    def _check_type(self, type_ref, value) -> bool:
        kind = type_ref[0]
        if kind == "non_null":
            return value is not None and self._check_type(type_ref[1], value)
        if value is None:
            return True
        if kind == "list":
            return isinstance(value, list) and all(
                self._check_type(type_ref[1], item) for item in value
            )
        name = type_ref[1]
        if name == "Int":
            return isinstance(value, int) and not isinstance(value, bool)
        if name == "Float":
            return isinstance(value, (int, float)) and not isinstance(value, bool)
        if name == "String":
            return isinstance(value, str)
        if name == "Boolean":
            return isinstance(value, bool)
        if name == "ID":
            return isinstance(value, (str, int)) and not isinstance(value, bool)
        if name in self.schema.scalars:
            return True
        if name in self.schema.enums:
            return isinstance(value, str)
        input_def = self.schema.inputs.get(name)
        if input_def is not None:
            if not isinstance(value, dict):
                return False
            for field_name, field_def in input_def.items():
                if (
                    field_def.type[0] == "non_null"
                    and not field_def.has_default
                    and field_name not in value
                ):
                    return False
                if field_name in value and not self._check_type(
                    field_def.type, value[field_name]
                ):
                    return False
            return True
        return True  # unknown named type: accept

    # -- roots ------------------------------------------------------------------

    def _plan_root(self, node: FieldNode, root_type: TypeInfo) -> dict:
        key = node.alias or node.name
        field = root_type.fields.get(node.name)
        if field is None:
            raise PlanError(
                "UnknownField", f"unknown root field '{node.name}' on type '{root_type.name}'"
            )
        type_name = named_of(field.type_ref)
        target = self.schema.types.get(type_name)
        entity = target.entity if target is not None else None
        if entity is None:
            raise PlanError(
                "UnknownEntity",
                f"root field '{node.name}' does not return a mapped entity type",
            )
        if node.selection_set is None:
            raise PlanError(
                "InvalidQuery", f"root field '{node.name}' requires a selection set"
            )
        for arg_name, arg_def in field.args.items():
            if (
                arg_def.type[0] == "non_null"
                and not arg_def.has_default
                and arg_name not in node.args
            ):
                raise PlanError(
                    "UnknownField",
                    f"missing required argument '{arg_name}' on root field '{node.name}'",
                )
        filter_obj: Dict[str, Any] = {}
        for arg_name, value in node.args.items():
            if arg_name not in field.args:
                raise PlanError(
                    "UnknownField",
                    f"unknown argument '{arg_name}' on root field '{node.name}'",
                )
            target_field = target.fields.get(arg_name)
            if target_field is None or not self.schema.is_leaf(
                named_of(target_field.type_ref)
            ):
                raise PlanError(
                    "UnknownField",
                    f"argument '{arg_name}' does not match a filterable field of entity '{entity.table}'",
                )
            filter_obj[arg_name] = self._resolve(value)
        entry = {"path": key, "entity": entity.table, "filter": filter_obj, "fields": []}
        self._walk(target, entity, node.selection_set, key, entry)
        return entry

    # -- nested selections --------------------------------------------------------

    def _walk(self, info: TypeInfo, entity, selection_set, path: str, entry: dict) -> None:
        selections = self._expand(selection_set, info.name, [])
        if not selections:
            raise PlanError("InvalidQuery", f"empty selection set at '{path}'")
        for node in selections:
            key = node.alias or node.name
            node_path = f"{path}.{key}"
            field = info.fields.get(node.name)
            if field is None:
                raise PlanError(
                    "UnknownField", f"unknown field '{node.name}' on type '{info.name}'"
                )
            type_name = named_of(field.type_ref)
            if self.schema.is_leaf(type_name):
                if node.selection_set is not None:
                    raise PlanError(
                        "InvalidQuery",
                        f"scalar field '{node.name}' must not have a selection set",
                    )
                if node.args:
                    raise PlanError(
                        "InvalidQuery",
                        f"arguments on field '{node.name}' are not supported",
                    )
                if node_path not in entry["fields"]:
                    entry["fields"].append(node_path)
                continue
            target = self.schema.types.get(type_name)
            if target is None:
                raise PlanError(
                    "UnknownField",
                    f"field '{node.name}' has unsupported type '{type_name}'",
                )
            if node.args:
                raise PlanError(
                    "InvalidQuery",
                    f"arguments on field '{node.name}' are not supported",
                )
            if node.selection_set is None:
                raise PlanError(
                    "InvalidQuery", f"field '{node.name}' requires a selection set"
                )
            if field.link is None:
                raise PlanError(
                    "MappingError",
                    f"field '{info.name}.{node.name}' is missing an @link directive",
                )
            target_entity = target.entity
            if target_entity is None:
                raise PlanError(
                    "UnknownEntity",
                    f"type '{target.name}' is not mapped to an entity",
                )
            local, target_key, as_array = field.link
            if target_key != target_entity.key:
                raise PlanError(
                    "InvalidJoin",
                    f"@link target {target_key} does not match the primary key of entity '{target_entity.table}'",
                )
            self.joins.append(
                {
                    "path": node_path,
                    "fromEntity": entity.table,
                    "fromField": local if as_array else local[0],
                    "toEntity": target_entity.table,
                    "toField": target_key if as_array else target_key[0],
                }
            )
            self._walk(target, target_entity, node.selection_set, node_path, entry)

"""Schema model: object types plus the @entity / @link mapping directives.

Mapping declaration problems (missing or conflicting entity/directive
declarations, dangling type references) raise PlanError "MappingError".
"""

from __future__ import annotations

from typing import Dict, List, Optional, Tuple

from .errors import PlanError
from .gql import Directive, TypeRef, parse_schema_document

BUILTIN_SCALARS = frozenset({"Int", "Float", "String", "Boolean", "ID"})


def named_of(type_ref: TypeRef) -> str:
    """Unwrap list/non-null wrappers down to the named type."""
    while type_ref[0] in ("list", "non_null"):
        type_ref = type_ref[1]
    return type_ref[1]


class Entity:
    __slots__ = ("type_name", "table", "key")

    def __init__(self, type_name: str, table: str, key: List[str]):
        self.type_name = type_name
        self.table = table
        self.key = key  # primary key field names, in declared order


class FieldInfo:
    __slots__ = ("name", "type_ref", "args", "link_directives", "link")

    def __init__(self, name, type_ref, args, link_directives):
        self.name = name
        self.type_ref = type_ref
        self.args = args  # Dict[str, InputValueDef]
        self.link_directives = link_directives
        # (local names, target names, declared_as_arrays) once validated
        self.link: Optional[Tuple[List[str], List[str], bool]] = None


class TypeInfo:
    __slots__ = ("name", "fields", "interfaces", "entity")

    def __init__(self, name: str, interfaces: List[str]):
        self.name = name
        self.fields: Dict[str, FieldInfo] = {}
        self.interfaces = interfaces
        self.entity: Optional[Entity] = None


class Schema:
    def __init__(self):
        self.types: Dict[str, TypeInfo] = {}
        self.scalars = set(BUILTIN_SCALARS)
        self.enums = set()
        self.inputs: Dict[str, Dict[str, object]] = {}
        self.interfaces = set()
        self.unions: Dict[str, List[str]] = {}
        self.roots: Dict[str, str] = {}  # "query" | "mutation" | "subscription" -> type name

    def is_leaf(self, type_name: str) -> bool:
        return type_name in self.scalars or type_name in self.enums

    def known_type(self, type_name: str) -> bool:
        return (
            type_name in self.scalars
            or type_name in self.enums
            or type_name in self.types
            or type_name in self.inputs
            or type_name in self.interfaces
            or type_name in self.unions
        )


def _mapping_error(message: str) -> PlanError:
    return PlanError("MappingError", message)


def load_schema(text: str, source: str = "<schema>") -> Schema:
    doc = parse_schema_document(text, source)
    schema = Schema()
    schema.scalars |= set(doc.scalars)
    schema.enums = set(doc.enums)
    schema.interfaces = {tdef.name for tdef in doc.interfaces}
    schema.unions = dict(doc.unions)

    for input_def in doc.inputs:
        if input_def.name in schema.inputs:
            raise _mapping_error(f"duplicate input type '{input_def.name}'")
        fields: Dict[str, object] = {}
        for fdef in input_def.fields:
            if fdef.name in fields:
                raise _mapping_error(
                    f"duplicate field '{fdef.name}' on input '{input_def.name}'"
                )
            fields[fdef.name] = fdef
        schema.inputs[input_def.name] = fields

    # Merge plain definitions with `extend type` blocks.
    slots: Dict[str, dict] = {}
    for tdef in doc.types:
        slot = slots.setdefault(
            tdef.name, {"fields": [], "directives": [], "interfaces": [], "defined": False}
        )
        if not tdef.is_extend:
            if slot["defined"]:
                raise _mapping_error(f"duplicate definition of type '{tdef.name}'")
            slot["defined"] = True
        slot["fields"].extend(tdef.fields)
        slot["directives"].extend(tdef.directives)
        for iface in tdef.interfaces:
            if iface not in slot["interfaces"]:
                slot["interfaces"].append(iface)

    reserved = set(schema.scalars) | schema.enums | set(schema.inputs) | schema.interfaces | set(schema.unions)
    for name in slots:
        if name in reserved:
            raise _mapping_error(f"name '{name}' is defined more than once")

    for name, slot in slots.items():
        info = TypeInfo(name, slot["interfaces"])
        for iface in slot["interfaces"]:
            if iface not in schema.interfaces:
                raise _mapping_error(f"type '{name}' implements unknown interface '{iface}'")
        for fdef in slot["fields"]:
            if fdef.name in info.fields:
                raise _mapping_error(f"duplicate field '{fdef.name}' on type '{name}'")
            args: Dict[str, object] = {}
            for adef in fdef.args:
                if adef.name in args:
                    raise _mapping_error(
                        f"duplicate argument '{adef.name}' on '{name}.{fdef.name}'"
                    )
                args[adef.name] = adef
            link_directives = [d for d in fdef.directives if d.name == "link"]
            info.fields[fdef.name] = FieldInfo(fdef.name, fdef.type, args, link_directives)
        entity_directives = [d for d in slot["directives"] if d.name == "entity"]
        if len(entity_directives) > 1:
            raise _mapping_error(f"type '{name}' has multiple @entity directives")
        if entity_directives:
            info.entity = _build_entity(schema, info, entity_directives[0])
        schema.types[name] = info

    _validate_type_references(schema)
    _validate_links(schema)
    _validate_entity_tables(schema)
    _resolve_roots(schema, doc.roots)
    return schema


def _normalize_field_list(value, what: str) -> Tuple[List[str], bool]:
    """Normalize a string-or-string-array directive argument.

    Returns (field names in declared order, declared_as_array). Anything
    else (empty arrays, non-string elements, duplicates, other types) is a
    MappingError.
    """
    if isinstance(value, str):
        if not value:
            raise _mapping_error(f"{what} requires a non-empty string")
        return [value], False
    if isinstance(value, list):
        if not value:
            raise _mapping_error(f"{what} must not be an empty array")
        names: List[str] = []
        for item in value:
            if not isinstance(item, str) or not item:
                raise _mapping_error(f"{what} must contain only non-empty strings")
            if item in names:
                raise _mapping_error(f"{what} contains duplicate field '{item}'")
            names.append(item)
        return names, True
    raise _mapping_error(f"{what} must be a string or an array of strings")


def _build_entity(schema: Schema, info: TypeInfo, directive: Directive) -> Entity:
    table = directive.args.get("name")
    if not isinstance(table, str) or not table:
        raise _mapping_error(f"@entity on '{info.name}' requires a non-empty string 'name'")
    key, _ = _normalize_field_list(
        directive.args.get("key"), f"@entity 'key' of type '{info.name}'"
    )
    for name in key:
        key_field = info.fields.get(name)
        if key_field is None:
            raise _mapping_error(f"@entity key '{name}' is not a field of type '{info.name}'")
        if named_of(key_field.type_ref) not in schema.scalars:
            raise _mapping_error(f"@entity key '{name}' of type '{info.name}' must be a scalar")
    return Entity(info.name, table, key)


def _validate_type_references(schema: Schema) -> None:
    def check(type_ref: TypeRef, where: str) -> None:
        name = named_of(type_ref)
        if not schema.known_type(name):
            raise _mapping_error(f"unknown type '{name}' referenced by {where}")

    for info in schema.types.values():
        for field in info.fields.values():
            check(field.type_ref, f"'{info.name}.{field.name}'")
            for arg in field.args.values():
                check(arg.type, f"argument '{arg.name}' of '{info.name}.{field.name}'")
    for input_name, fields in schema.inputs.items():
        for fdef in fields.values():
            check(fdef.type, f"input field '{input_name}.{fdef.name}'")
    for union_name, members in schema.unions.items():
        for member in members:
            if member not in schema.types:
                raise _mapping_error(f"union '{union_name}' references unknown type '{member}'")


def _validate_links(schema: Schema) -> None:
    for info in schema.types.values():
        for field in info.fields.values():
            directives = field.link_directives
            if len(directives) > 1:
                raise _mapping_error(f"field '{info.name}.{field.name}' has multiple @link directives")
            if not directives:
                continue
            directive = directives[0]
            where = f"@link on '{info.name}.{field.name}'"
            local, local_is_array = _normalize_field_list(
                directive.args.get("local"), f"{where} argument 'local'"
            )
            target, target_is_array = _normalize_field_list(
                directive.args.get("target"), f"{where} argument 'target'"
            )
            if local_is_array != target_is_array:
                raise _mapping_error(
                    f"{where} must use the same form (string or array) for 'local' and 'target'"
                )
            if len(local) != len(target):
                raise _mapping_error(
                    f"{where} has {len(local)} local field(s) but {len(target)} target field(s)"
                )
            target_type = named_of(field.type_ref)
            target_info = schema.types.get(target_type)
            if target_info is None:
                raise _mapping_error(
                    f"@link on '{info.name}.{field.name}' must point to an object type"
                )
            for name in local:
                local_field = info.fields.get(name)
                if local_field is None:
                    raise _mapping_error(
                        f"@link local field '{name}' is not a field of type '{info.name}'"
                    )
                if named_of(local_field.type_ref) not in schema.scalars:
                    raise _mapping_error(
                        f"@link local field '{name}' of type '{info.name}' must be a scalar"
                    )
            for name in target:
                if name not in target_info.fields:
                    raise _mapping_error(
                        f"@link target field '{name}' is not a field of type '{target_type}'"
                    )
            field.link = (local, target, local_is_array)


def _validate_entity_tables(schema: Schema) -> None:
    tables: Dict[str, str] = {}
    for info in schema.types.values():
        if info.entity is None:
            continue
        other = tables.get(info.entity.table)
        if other is not None:
            raise _mapping_error(
                f"entity '{info.entity.table}' is mapped by both '{other}' and '{info.name}'"
            )
        tables[info.entity.table] = info.name


def _resolve_roots(schema: Schema, declared: Dict[str, str]) -> None:
    for op, default_name in (("query", "Query"), ("mutation", "Mutation"), ("subscription", "Subscription")):
        if default_name in schema.types:
            schema.roots[op] = default_name
    for op, type_name in declared.items():
        if type_name not in schema.types:
            raise _mapping_error(f"root type '{type_name}' for {op} is not defined")
        schema.roots[op] = type_name

"""End-to-end tests for `graph-index subscription-push`."""

import contextlib
import io
import json
import os
import tempfile
import unittest

from graph_index.cli import main

SCHEMA = """\
type Query {
  users: [User!]!
}

type Subscription {
  users(id: ID, status: String, role: Role): [User!]!
  user(id: ID!): User
  teams: [Team!]!
}

enum Role {
  ADMIN
  MEMBER
}

type User @entity(name: "users", key: "id") {
  id: ID!
  name: String!
  status: String
  role: Role
  tags: [String!]
  team_id: ID
  team: Team @link(local: "team_id", target: "id")
}

type Team @entity(name: "teams", key: "id") {
  id: ID!
  name: String!
}
"""

EVENTS = "\n".join(
    [
        json.dumps(row)
        for row in [
            {"op": "INSERT", "entity": "users", "before": None,
             "after": {"id": 1, "name": "ada", "status": "active",
                       "role": "ADMIN", "tags": ["a", "b"], "team_id": 9}},
            {"op": "INSERT", "entity": "teams", "before": None,
             "after": {"id": 9, "name": "core"}},
            {"op": "UPDATE", "entity": "users",
             "before": {"id": 1, "name": "ada", "status": "active",
                        "role": "ADMIN", "tags": ["a", "b"], "team_id": 9},
             "after": {"id": 1, "name": "ada", "status": "banned",
                       "role": "ADMIN", "tags": ["a"], "team_id": 9}},
            {"op": "DELETE", "entity": "users",
             "before": {"id": 2, "name": "bob", "status": "active",
                        "role": "MEMBER", "tags": [], "team_id": None},
             "after": None},
        ]
    ]
) + "\n"

COMPOSITE_SCHEMA = """\
type Query {
  transfers: [Transfer!]!
}

type Subscription {
  transfers(chain_id: Int, id: ID): [Transfer!]!
}

type Transfer @entity(name: "transfers", key: ["chain_id", "id"]) {
  chain_id: Int!
  id: ID!
  amount: Float
  token_chain: Int
  token_id: ID
  token: Token @link(local: ["token_chain", "token_id"], target: ["chain_id", "id"])
}

type Token @entity(name: "tokens", key: ["chain_id", "id"]) {
  chain_id: Int!
  id: ID!
  symbol: String!
}
"""


class CliCase(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)

    def _write(self, name, content, mode="w"):
        path = os.path.join(self.tmp.name, name)
        with open(path, mode) as handle:
            handle.write(content)
        return path

    def run_cli(self, subscription, variables="{}", schema=SCHEMA, events=EVENTS,
                operation=None):
        schema_path = self._write("schema.graphql", schema)
        subscription_path = self._write("subscription.graphql", subscription)
        variables_path = self._write("variables.json", variables)
        events_path = self._write("events.ndjson", events)
        argv = ["subscription-push", "--schema", schema_path,
                "--subscription", subscription_path,
                "--variables", variables_path,
                "--events", events_path]
        if operation is not None:
            argv += ["--operation", operation]
        stdout, stderr = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(stdout), contextlib.redirect_stderr(stderr):
            code = main(argv)
        return code, stdout.getvalue(), stderr.getvalue()

    def assert_error(self, code, stdout, stderr, expected_code):
        self.assertEqual(code, 2, stdout)
        self.assertEqual(stdout, "")
        payload = json.loads(stderr)
        self.assertEqual(payload["code"], expected_code)
        self.assertIsInstance(payload["message"], str)
        self.assertTrue(payload["message"])

    def assert_rows(self, code, stdout, stderr):
        self.assertEqual(stderr, "")
        self.assertEqual(code, 0, stderr)
        return [json.loads(line) for line in stdout.splitlines()]

    # -- happy paths ---------------------------------------------------------

    def test_no_filter_collects_all_entity_events_in_order(self):
        rows = self.assert_rows(*self.run_cli("subscription { users { id name } }"))
        self.assertEqual([r["event"] for r in rows], ["INSERT", "UPDATE", "DELETE"])
        for row in rows:
            self.assertIsNone(row["subscription"])
            self.assertEqual(row["path"], "users")
            self.assertEqual(row["entity"], "users")
        self.assertEqual(rows[0]["data"], {"id": 1, "name": "ada"})
        self.assertEqual(rows[1]["data"], {"id": 1, "name": "ada"})
        self.assertEqual(rows[2]["data"], {"id": 2, "name": "bob"})

    def test_filter_with_variable_and_literal(self):
        subscription = """
        subscription Watch($status: String) {
          users(status: $status, role: ADMIN) { id }
        }
        """
        rows = self.assert_rows(*self.run_cli(subscription, '{"status": "active"}'))
        self.assertEqual(len(rows), 1)
        self.assertEqual(rows[0]["subscription"], "Watch")
        self.assertEqual(rows[0]["event"], "INSERT")
        self.assertEqual(rows[0]["data"], {"id": 1})

    def test_delete_uses_before_snapshot(self):
        rows = self.assert_rows(*self.run_cli("subscription { users(status: \"active\") { id } }"))
        self.assertEqual([r["event"] for r in rows], ["INSERT", "DELETE"])
        self.assertEqual(rows[1]["data"], {"id": 2})

    def test_alias_and_list_preserved(self):
        subscription = "subscription { me: users { userId: id tags } }"
        rows = self.assert_rows(*self.run_cli(subscription))
        self.assertEqual(rows[0]["path"], "me")
        self.assertEqual(rows[0]["data"], {"userId": 1, "tags": ["a", "b"]})

    def test_variable_default_used_when_not_provided(self):
        subscription = (
            "subscription ($status: String = \"banned\") "
            "{ users(status: $status) { id } }"
        )
        rows = self.assert_rows(*self.run_cli(subscription))
        self.assertEqual([r["event"] for r in rows], ["UPDATE"])

    def test_operation_selected_by_name(self):
        subscription = """
        query Ignore { users { id } }
        subscription A { users { id } }
        subscription B { teams { id } }
        """
        rows = self.assert_rows(*self.run_cli(subscription, operation="B"))
        self.assertEqual(len(rows), 1)
        self.assertEqual(rows[0]["subscription"], "B")
        self.assertEqual(rows[0]["entity"], "teams")
        self.assertEqual(rows[0]["data"], {"id": 9})

    def test_fragments_expanded(self):
        subscription = """
        subscription { users { id ...Bits } }
        fragment Bits on User { name }
        """
        rows = self.assert_rows(*self.run_cli(subscription))
        self.assertEqual(rows[0]["data"], {"id": 1, "name": "ada"})

    def test_no_matching_events_outputs_nothing(self):
        code, stdout, stderr = self.run_cli(
            "subscription { users(status: \"nope\") { id } }"
        )
        self.assertEqual((code, stdout, stderr), (0, "", ""))

    def test_blank_event_lines_skipped(self):
        events = "\n" + EVENTS.replace("\n", "\n\n")
        rows = self.assert_rows(*self.run_cli("subscription { users { id } }",
                                              events=events))
        self.assertEqual(len(rows), 3)

    # -- operation selection errors -------------------------------------------

    def test_non_subscription_operation_rejected(self):
        self.assert_error(
            *self.run_cli("query { users { id } }"), "InvalidQuery"
        )

    def test_multiple_operations_require_name(self):
        subscription = "subscription A { users { id } } subscription B { users { id } }"
        self.assert_error(*self.run_cli(subscription), "InvalidQuery")

    def test_operation_name_must_match_a_subscription(self):
        subscription = "query A { users { id } } subscription B { users { id } }"
        self.assert_error(*self.run_cli(subscription, operation="A"), "InvalidQuery")
        self.assert_error(*self.run_cli(subscription, operation="Nope"), "InvalidQuery")

    def test_multiple_root_fields_rejected(self):
        self.assert_error(
            *self.run_cli("subscription { users { id } teams { id } }"),
            "InvalidQuery",
        )

    # -- selection / filter errors ----------------------------------------------

    def test_empty_selection(self):
        self.assert_error(*self.run_cli("subscription { users { } }"), "InvalidQuery")

    def test_unknown_root_field(self):
        self.assert_error(*self.run_cli("subscription { nope { id } }"), "InvalidQuery")

    def test_unknown_leaf_field(self):
        self.assert_error(
            *self.run_cli("subscription { users { nope } }"), "InvalidQuery"
        )

    def test_leaf_with_selection(self):
        self.assert_error(
            *self.run_cli("subscription { users { id { x } } }"), "InvalidQuery"
        )

    def test_nested_object_unsupported(self):
        self.assert_error(
            *self.run_cli("subscription { users { team { id } } }"),
            "UnsupportedSelection",
        )

    def test_unknown_argument(self):
        self.assert_error(
            *self.run_cli("subscription { users(nope: 1) { id } }"), "InvalidQuery"
        )

    def test_argument_not_an_entity_field(self):
        schema = SCHEMA.replace("users(id: ID, status: String, role: Role)",
                                "users(id: ID, age: Int)")
        self.assert_error(
            *self.run_cli("subscription { users(age: 3) { id } }", schema=schema),
            "InvalidQuery",
        )

    def test_missing_required_argument(self):
        self.assert_error(
            *self.run_cli("subscription { user { id } }"), "InvalidQuery"
        )

    # -- mapping errors ------------------------------------------------------------

    def test_no_subscription_root_type(self):
        schema = "type Query { users: [User!]! }\n" \
                 "type User @entity(name: \"users\", key: \"id\") { id: ID! }\n"
        self.assert_error(
            *self.run_cli("subscription { users { id } }", schema=schema),
            "MappingError",
        )

    def test_root_return_type_not_entity(self):
        schema = SCHEMA + "extend type Subscription { version: Version }\n" \
                          "type Version { tag: String }\n"
        self.assert_error(
            *self.run_cli("subscription { version { tag } }", schema=schema),
            "MappingError",
        )

    # -- variables errors -------------------------------------------------------------

    def test_variable_missing(self):
        self.assert_error(
            *self.run_cli("subscription ($id: ID!) { users(id: $id) { id } }"),
            "VariablesError",
        )

    def test_variable_wrong_type(self):
        self.assert_error(
            *self.run_cli("subscription ($id: ID) { users(id: $id) { id } }",
                          '{"id": {}}'),
            "VariablesError",
        )

    def test_variable_undeclared(self):
        self.assert_error(
            *self.run_cli("subscription { users(id: $id) { id } }", '{"id": 1}'),
            "VariablesError",
        )

    def test_variables_file_not_an_object(self):
        self.assert_error(
            *self.run_cli("subscription { users { id } }", "[1, 2]"),
            "VariablesError",
        )

    # -- event errors ------------------------------------------------------------------

    def _events_error(self, events, expected="EventError"):
        self.assert_error(
            *self.run_cli("subscription { users { id } }", events=events), expected
        )

    def test_event_invalid_json(self):
        self._events_error("{not json\n")

    def test_event_not_an_object(self):
        self._events_error("[1, 2]\n")

    def test_event_missing_key(self):
        self._events_error('{"op": "INSERT", "entity": "users", "after": {}}\n')

    def test_event_unknown_op(self):
        self._events_error(
            '{"op": "UPSERT", "entity": "users", "before": null, "after": {}}\n'
        )

    def test_event_snapshot_not_object(self):
        self._events_error(
            '{"op": "INSERT", "entity": "users", "before": null, "after": 5}\n'
        )

    def test_event_insert_without_snapshot(self):
        self._events_error(
            '{"op": "INSERT", "entity": "users", "before": null, "after": null}\n'
        )

    def test_event_delete_without_snapshot(self):
        self._events_error(
            '{"op": "DELETE", "entity": "users", "before": null, "after": null}\n'
        )

    def test_event_snapshot_missing_selected_field(self):
        self._events_error(
            '{"op": "INSERT", "entity": "users", "before": null, "after": {"name": "ada"}}\n'
        )

    def test_event_snapshot_missing_filter_field(self):
        self.assert_error(
            *self.run_cli(
                "subscription { users(status: \"active\") { id } }",
                events='{"op": "INSERT", "entity": "users", "before": null, "after": {"id": 1}}\n',
            ),
            "EventError",
        )

    def test_event_for_other_entity_with_null_snapshots_skipped(self):
        events = '{"op": "DELETE", "entity": "teams", "before": null, "after": null}\n'
        code, stdout, stderr = self.run_cli("subscription { users { id } }",
                                            events=events)
        self.assertEqual((code, stdout, stderr), (0, "", ""))

    # -- parse / io errors --------------------------------------------------------------

    def test_subscription_parse_error(self):
        self.assert_error(
            *self.run_cli("subscription { users { id "), "ParseError"
        )

    def test_variables_parse_error(self):
        self.assert_error(
            *self.run_cli("subscription { users { id } }", "{not json"), "ParseError"
        )

    def test_missing_events_file(self):
        schema_path = self._write("schema.graphql", SCHEMA)
        subscription_path = self._write("subscription.graphql",
                                        "subscription { users { id } }")
        variables_path = self._write("variables.json", "{}")
        argv = ["subscription-push", "--schema", schema_path,
                "--subscription", subscription_path,
                "--variables", variables_path,
                "--events", "/nonexistent/events.ndjson"]
        stdout, stderr = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(stdout), contextlib.redirect_stderr(stderr):
            code = main(argv)
        self.assert_error(code, stdout.getvalue(), stderr.getvalue(), "IoError")

    # -- composite keys ---------------------------------------------------------

    def test_composite_key_schema_pushes_events(self):
        events = "\n".join(
            json.dumps(row)
            for row in [
                {"op": "INSERT", "entity": "transfers", "before": None,
                 "after": {"chain_id": 1, "id": "t1", "amount": 3.5}},
                {"op": "INSERT", "entity": "transfers", "before": None,
                 "after": {"chain_id": 2, "id": "t2", "amount": 1.0}},
            ]
        ) + "\n"
        subscription = "subscription { transfers(chain_id: 1) { chain_id id } }"
        rows = self.assert_rows(
            *self.run_cli(subscription, schema=COMPOSITE_SCHEMA, events=events)
        )
        self.assertEqual(len(rows), 1)
        self.assertEqual(rows[0]["entity"], "transfers")
        self.assertEqual(rows[0]["data"], {"chain_id": 1, "id": "t1"})

    def test_invalid_composite_mapping_produces_no_output(self):
        schema = COMPOSITE_SCHEMA.replace(
            'key: ["chain_id", "id"]', 'key: ["chain_id", "chain_id"]', 1
        )
        self.assert_error(
            *self.run_cli("subscription { transfers { id } }", schema=schema),
            "MappingError",
        )


if __name__ == "__main__":
    unittest.main()

"""Self-contained GraphQL lexer and parser.

Parses both schema definition documents (SDL) and executable documents
(operations, fragments) into small dataclass ASTs. Syntax problems raise
PlanError with code "ParseError".
"""

from __future__ import annotations

import re
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Tuple

from .errors import PlanError

PUNCTUATORS = set("!$():=@[]{|}&")
NUMBER_RE = re.compile(r"-?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?(?:[eE][+-]?[0-9]+)?")

# Type references are nested tuples: ("named", name) | ("list", ref) | ("non_null", ref).
TypeRef = Tuple


# ---------------------------------------------------------------------------
# AST nodes
# ---------------------------------------------------------------------------


@dataclass
class Var:
    name: str


@dataclass
class Directive:
    name: str
    args: Dict[str, Any]


@dataclass
class InputValueDef:
    name: str
    type: TypeRef
    default: Any = None
    has_default: bool = False


@dataclass
class FieldDef:
    name: str
    args: List[InputValueDef]
    type: TypeRef
    directives: List[Directive]


@dataclass
class ObjectTypeDef:
    name: str
    fields: List[FieldDef]
    directives: List[Directive]
    interfaces: List[str]
    is_extend: bool = False


@dataclass
class InputDef:
    name: str
    fields: List[InputValueDef]


@dataclass
class Operation:
    op_type: str  # "query" | "mutation" | "subscription"
    name: Optional[str]
    var_defs: List[Tuple[str, TypeRef, Any, bool]]  # (name, type, default, has_default)
    selection_set: list


@dataclass
class FieldNode:
    name: str
    alias: Optional[str]
    args: Dict[str, Any]
    selection_set: Optional[list]  # None when the field has no subselection


@dataclass
class FragmentSpread:
    name: str


@dataclass
class InlineFragment:
    type_condition: Optional[str]
    selection_set: list


@dataclass
class FragmentDef:
    name: str
    type_condition: str
    selection_set: list


@dataclass
class Token:
    kind: str  # "name" | "int" | "float" | "string" | "punct" | "eof"
    value: str
    line: int
    col: int


# ---------------------------------------------------------------------------
# Lexer
# ---------------------------------------------------------------------------


def tokenize(text: str, source: str) -> List[Token]:
    tokens: List[Token] = []
    i = 0
    line = 1
    col = 1
    n = len(text)

    def error(message: str, ln: Optional[int] = None, cl: Optional[int] = None):
        raise PlanError("ParseError", f"{source}:{ln or line}:{cl or col}: {message}")

    while i < n:
        ch = text[i]
        if ch in " \t\r\n,":
            if ch == "\n":
                line += 1
                col = 1
            else:
                col += 1
            i += 1
            continue
        if ch == "#":
            while i < n and text[i] != "\n":
                i += 1
                col += 1
            continue
        start_line, start_col = line, col
        if ch == ".":
            if text[i : i + 3] == "...":
                tokens.append(Token("punct", "...", start_line, start_col))
                i += 3
                col += 3
                continue
            error("unexpected character '.'")
        if ch in PUNCTUATORS:
            tokens.append(Token("punct", ch, start_line, start_col))
            i += 1
            col += 1
            continue
        if ch == '"':
            if text[i : i + 3] == '"""':
                j = i + 3
                buf: List[str] = []
                closed = False
                while j < n:
                    if text[j] == "\\" and text[j + 1 : j + 4] == '"""':
                        buf.append('"""')
                        j += 4
                    elif text[j : j + 3] == '"""':
                        closed = True
                        break
                    else:
                        buf.append(text[j])
                        j += 1
                if not closed:
                    error("unterminated block string", start_line, start_col)
                segment = text[i : j + 3]
                tokens.append(Token("string", "".join(buf), start_line, start_col))
                i = j + 3
            else:
                j = i + 1
                buf = []
                closed = False
                while j < n:
                    c = text[j]
                    if c == '"':
                        closed = True
                        break
                    if c == "\n":
                        error("unterminated string", start_line, start_col)
                    if c == "\\":
                        esc = text[j + 1] if j + 1 < n else ""
                        simple = {
                            '"': '"',
                            "\\": "\\",
                            "/": "/",
                            "b": "\b",
                            "f": "\f",
                            "n": "\n",
                            "r": "\r",
                            "t": "\t",
                        }
                        if esc == "u":
                            hexs = text[j + 2 : j + 6]
                            if len(hexs) < 4 or any(
                                c2 not in "0123456789abcdefABCDEF" for c2 in hexs
                            ):
                                error("invalid unicode escape", start_line, start_col)
                            buf.append(chr(int(hexs, 16)))
                            j += 6
                        elif esc in simple:
                            buf.append(simple[esc])
                            j += 2
                        else:
                            error(f"invalid escape '\\{esc}'", start_line, start_col)
                    else:
                        buf.append(c)
                        j += 1
                if not closed:
                    error("unterminated string", start_line, start_col)
                segment = text[i : j + 1]
                tokens.append(Token("string", "".join(buf), start_line, start_col))
                i = j + 1
            newlines = segment.count("\n")
            if newlines:
                line += newlines
                col = len(segment) - segment.rindex("\n")
            else:
                col += len(segment)
            continue
        if ch == "-" or ch.isdigit():
            m = NUMBER_RE.match(text, i)
            if not m:
                error("invalid number", start_line, start_col)
            sval = m.group(0)
            kind = "float" if ("." in sval or "e" in sval or "E" in sval) else "int"
            tokens.append(Token(kind, sval, start_line, start_col))
            i = m.end()
            col += len(sval)
            continue
        if ch.isalpha() or ch == "_":
            j = i
            while j < n and (text[j].isalnum() or text[j] == "_"):
                j += 1
            tokens.append(Token("name", text[i:j], start_line, start_col))
            col += j - i
            i = j
            continue
        error(f"unexpected character {ch!r}")
    tokens.append(Token("eof", "", line, col))
    return tokens


# ---------------------------------------------------------------------------
# Parser
# ---------------------------------------------------------------------------


class Parser:
    def __init__(self, text: str, source: str):
        self.source = source
        self.tokens = tokenize(text, source)
        self.pos = 0

    def peek(self) -> Token:
        return self.tokens[self.pos]

    def error(self, message: str) -> "PlanError":
        tok = self.peek()
        raise PlanError("ParseError", f"{self.source}:{tok.line}:{tok.col}: {message}")

    def describe(self) -> str:
        tok = self.peek()
        if tok.kind == "eof":
            return "end of input"
        return repr(tok.value)

    def advance(self) -> Token:
        tok = self.tokens[self.pos]
        if tok.kind != "eof":
            self.pos += 1
        return tok

    def at_punct(self, p: str) -> bool:
        tok = self.peek()
        return tok.kind == "punct" and tok.value == p

    def eat_punct(self, p: str) -> bool:
        if self.at_punct(p):
            self.advance()
            return True
        return False

    def expect_punct(self, p: str) -> None:
        if not self.eat_punct(p):
            self.error(f"expected '{p}', found {self.describe()}")

    def at_name(self, name: Optional[str] = None) -> bool:
        tok = self.peek()
        return tok.kind == "name" and (name is None or tok.value == name)

    def expect_name(self) -> str:
        tok = self.peek()
        if tok.kind != "name":
            self.error(f"expected a name, found {self.describe()}")
        self.advance()
        return tok.value

    # -- types ---------------------------------------------------------------

    def parse_type_ref(self) -> TypeRef:
        if self.eat_punct("["):
            inner = self.parse_type_ref()
            self.expect_punct("]")
            ref: TypeRef = ("list", inner)
        else:
            ref = ("named", self.expect_name())
        if self.eat_punct("!"):
            ref = ("non_null", ref)
        return ref

    # -- values ----------------------------------------------------------------

    def parse_value(self, const: bool = False) -> Any:
        tok = self.peek()
        if tok.kind == "punct" and tok.value == "$":
            if const:
                self.error("variables are not allowed in this position")
            self.advance()
            return Var(self.expect_name())
        if tok.kind == "int":
            self.advance()
            return int(tok.value)
        if tok.kind == "float":
            self.advance()
            return float(tok.value)
        if tok.kind == "string":
            self.advance()
            return tok.value
        if tok.kind == "name":
            self.advance()
            if tok.value == "true":
                return True
            if tok.value == "false":
                return False
            if tok.value == "null":
                return None
            return tok.value  # enum value
        if self.eat_punct("["):
            items = []
            while not self.eat_punct("]"):
                items.append(self.parse_value(const))
            return items
        if self.eat_punct("{"):
            obj: Dict[str, Any] = {}
            while not self.eat_punct("}"):
                key = self.expect_name()
                if key in obj:
                    self.error(f"duplicate object field '{key}'")
                self.expect_punct(":")
                obj[key] = self.parse_value(const)
            return obj
        self.error(f"expected a value, found {self.describe()}")

    def parse_directives(self, const: bool = False) -> List[Directive]:
        directives = []
        while self.eat_punct("@"):
            name = self.expect_name()
            args: Dict[str, Any] = {}
            if self.eat_punct("("):
                while not self.eat_punct(")"):
                    arg_name = self.expect_name()
                    if arg_name in args:
                        self.error(f"duplicate argument '{arg_name}' on '@{name}'")
                    self.expect_punct(":")
                    args[arg_name] = self.parse_value(const)
            directives.append(Directive(name, args))
        return directives

    # -- executable documents ---------------------------------------------------

    def parse_selection_set(self) -> list:
        self.expect_punct("{")
        selections = []
        while not self.at_punct("}"):
            if self.peek().kind == "eof":
                self.error("unterminated selection set")
            selections.append(self.parse_selection())
        self.expect_punct("}")
        return selections

    def parse_selection(self):
        if self.eat_punct("..."):
            if self.at_name("on"):
                self.advance()
                condition = self.expect_name()
                self.parse_directives()
                return InlineFragment(condition, self.parse_selection_set())
            if self.at_punct("{") or self.at_punct("@"):
                self.parse_directives()
                return InlineFragment(None, self.parse_selection_set())
            name = self.expect_name()
            self.parse_directives()
            return FragmentSpread(name)
        first = self.expect_name()
        alias = None
        name = first
        if self.eat_punct(":"):
            alias = first
            name = self.expect_name()
        args: Dict[str, Any] = {}
        if self.eat_punct("("):
            while not self.eat_punct(")"):
                arg_name = self.expect_name()
                if arg_name in args:
                    self.error(f"duplicate argument '{arg_name}'")
                self.expect_punct(":")
                args[arg_name] = self.parse_value()
        self.parse_directives()
        selection_set = None
        if self.at_punct("{"):
            selection_set = self.parse_selection_set()
        return FieldNode(name, alias, args, selection_set)


def parse_executable(text: str, source: str):
    """Parse an executable document. Returns (operations, fragments)."""
    parser = Parser(text, source)
    operations: List[Operation] = []
    fragments: Dict[str, FragmentDef] = {}
    while parser.peek().kind != "eof":
        if parser.at_punct("{"):
            operations.append(Operation("query", None, [], parser.parse_selection_set()))
            continue
        if parser.at_name("query") or parser.at_name("mutation") or parser.at_name("subscription"):
            op_type = parser.advance().value
            name = None
            if parser.peek().kind == "name":
                name = parser.advance().value
            var_defs = []
            if parser.eat_punct("("):
                while not parser.eat_punct(")"):
                    parser.expect_punct("$")
                    var_name = parser.expect_name()
                    parser.expect_punct(":")
                    var_type = parser.parse_type_ref()
                    default = None
                    has_default = False
                    if parser.eat_punct("="):
                        default = parser.parse_value(const=True)
                        has_default = True
                    parser.parse_directives(const=True)
                    var_defs.append((var_name, var_type, default, has_default))
            parser.parse_directives()
            operations.append(Operation(op_type, name, var_defs, parser.parse_selection_set()))
            continue
        if parser.at_name("fragment"):
            parser.advance()
            frag_name = parser.expect_name()
            if frag_name == "on":
                parser.error("fragment name cannot be 'on'")
            if not parser.at_name("on"):
                parser.error("expected 'on' after fragment name")
            parser.advance()
            condition = parser.expect_name()
            parser.parse_directives()
            selection_set = parser.parse_selection_set()
            if frag_name in fragments:
                parser.error(f"duplicate fragment '{frag_name}'")
            fragments[frag_name] = FragmentDef(frag_name, condition, selection_set)
            continue
        parser.error(f"unexpected {parser.describe()}")
    return operations, fragments


# ---------------------------------------------------------------------------
# Schema (SDL) documents
# ---------------------------------------------------------------------------


class SdlDocument:
    def __init__(self):
        self.types: List[ObjectTypeDef] = []
        self.interfaces: List[ObjectTypeDef] = []
        self.inputs: List[InputDef] = []
        self.scalars: List[str] = []
        self.enums: List[str] = []
        self.unions: Dict[str, List[str]] = {}
        self.roots: Dict[str, str] = {}
        self.schema_seen = False


def _parse_field_def(parser: Parser) -> FieldDef:
    name = parser.expect_name()
    args: List[InputValueDef] = []
    if parser.eat_punct("("):
        while not parser.eat_punct(")"):
            if parser.peek().kind == "string":
                parser.advance()  # argument description
            args.append(_parse_input_value_def(parser))
    parser.expect_punct(":")
    type_ref = parser.parse_type_ref()
    directives = parser.parse_directives(const=True)
    return FieldDef(name, args, type_ref, directives)


def _parse_input_value_def(parser: Parser) -> InputValueDef:
    name = parser.expect_name()
    parser.expect_punct(":")
    type_ref = parser.parse_type_ref()
    default = None
    has_default = False
    if parser.eat_punct("="):
        default = parser.parse_value(const=True)
        has_default = True
    parser.parse_directives(const=True)
    return InputValueDef(name, type_ref, default, has_default)


def _parse_object_type(parser: Parser, is_extend: bool) -> ObjectTypeDef:
    name = parser.expect_name()
    interfaces: List[str] = []
    if parser.at_name("implements"):
        parser.advance()
        parser.eat_punct("&")
        interfaces.append(parser.expect_name())
        while parser.eat_punct("&"):
            interfaces.append(parser.expect_name())
    directives = parser.parse_directives(const=True)
    fields: List[FieldDef] = []
    if parser.eat_punct("{"):
        while not parser.eat_punct("}"):
            if parser.peek().kind == "string":
                parser.advance()  # field description
            fields.append(_parse_field_def(parser))
    return ObjectTypeDef(name, fields, directives, interfaces, is_extend)


def _parse_schema_body(parser: Parser, doc: SdlDocument) -> None:
    parser.parse_directives(const=True)
    parser.expect_punct("{")
    while not parser.eat_punct("}"):
        op = parser.expect_name()
        if op not in ("query", "mutation", "subscription"):
            parser.error(f"unknown root operation '{op}'")
        parser.expect_punct(":")
        type_name = parser.expect_name()
        if op in doc.roots:
            parser.error(f"duplicate root operation '{op}'")
        doc.roots[op] = type_name


def parse_schema_document(text: str, source: str) -> SdlDocument:
    parser = Parser(text, source)
    doc = SdlDocument()
    while parser.peek().kind != "eof":
        if parser.peek().kind == "string":
            parser.advance()  # definition description
        if parser.at_name("schema"):
            if doc.schema_seen:
                parser.error("duplicate schema definition")
            doc.schema_seen = True
            parser.advance()
            _parse_schema_body(parser, doc)
        elif parser.at_name("scalar"):
            parser.advance()
            doc.scalars.append(parser.expect_name())
            parser.parse_directives(const=True)
        elif parser.at_name("type"):
            parser.advance()
            doc.types.append(_parse_object_type(parser, is_extend=False))
        elif parser.at_name("interface"):
            parser.advance()
            doc.interfaces.append(_parse_object_type(parser, is_extend=False))
        elif parser.at_name("input"):
            parser.advance()
            name = parser.expect_name()
            parser.parse_directives(const=True)
            fields: List[InputValueDef] = []
            if parser.eat_punct("{"):
                while not parser.eat_punct("}"):
                    if parser.peek().kind == "string":
                        parser.advance()
                    fields.append(_parse_input_value_def(parser))
            doc.inputs.append(InputDef(name, fields))
        elif parser.at_name("enum"):
            parser.advance()
            doc.enums.append(parser.expect_name())
            parser.parse_directives(const=True)
            if parser.eat_punct("{"):
                while not parser.eat_punct("}"):
                    if parser.peek().kind == "string":
                        parser.advance()
                    parser.expect_name()
                    parser.parse_directives(const=True)
        elif parser.at_name("union"):
            parser.advance()
            union_name = parser.expect_name()
            parser.parse_directives(const=True)
            members: List[str] = []
            if parser.eat_punct("="):
                parser.eat_punct("|")
                members.append(parser.expect_name())
                while parser.eat_punct("|"):
                    members.append(parser.expect_name())
            doc.unions[union_name] = members
        elif parser.at_name("directive"):
            parser.advance()
            parser.expect_punct("@")
            parser.expect_name()
            if parser.eat_punct("("):
                while not parser.eat_punct(")"):
                    _parse_input_value_def(parser)
            if parser.at_name("repeatable"):
                parser.advance()
            if not parser.at_name("on"):
                parser.error("expected 'on' in directive definition")
            parser.advance()
            parser.eat_punct("|")
            parser.expect_name()
            while parser.eat_punct("|"):
                parser.expect_name()
        elif parser.at_name("extend"):
            parser.advance()
            if parser.at_name("type"):
                parser.advance()
                doc.types.append(_parse_object_type(parser, is_extend=True))
            elif parser.at_name("schema"):
                parser.advance()
                _parse_schema_body(parser, doc)
            else:
                parser.error("unsupported 'extend' target")
        else:
            parser.error(f"unexpected {parser.describe()}")
    return doc

"""End-to-end tests for `graph-index query-plan`."""

import contextlib
import io
import json
import os
import tempfile
import unittest

from graph_index.cli import main

SCHEMA = """\
type Query {
  users(id: ID, name: String): [User!]!
  user(id: ID!): User
  teams: [Team!]!
}

type Mutation {
  createUser(name: String!): User
}

type User @entity(name: "users", key: "id") {
  id: ID!
  name: String!
  team_id: ID
  team: Team @link(local: "team_id", target: "id")
}

type Team @entity(name: "teams", key: "id") {
  id: ID!
  name: String!
  members: [User!]! @link(local: "id", target: "team_id")
}
"""

COMPOSITE_SCHEMA = """\
type Query {
  transfers(chain_id: Int, id: ID): [Transfer!]!
}

type Transfer @entity(name: "transfers", key: ["chain_id", "id"]) {
  chain_id: Int!
  id: ID!
  amount: Float
  token_chain: Int
  token_id: ID
  token: Token @link(local: ["token_chain", "token_id"], target: ["chain_id", "id"])
}

type Token @entity(name: "tokens", key: ["chain_id", "id"]) {
  chain_id: Int!
  id: ID!
  symbol: String!
}
"""


class CliCase(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)
        self.schema_path = self._write("schema.graphql", SCHEMA)
        self.variables_path = self._write("variables.json", "{}")

    def _write(self, name, content, mode="w"):
        path = os.path.join(self.tmp.name, name)
        with open(path, mode) as handle:
            handle.write(content)
        return path

    def run_cli(self, query, variables="{}", schema=SCHEMA, operation=None,
                query_name="query.graphql"):
        query_path = self._write(query_name, query)
        variables_path = self._write("variables.json", variables)
        schema_path = self._write("schema.graphql", schema)
        argv = ["query-plan", "--schema", schema_path, "--query", query_path,
                "--variables", variables_path]
        if operation is not None:
            argv += ["--operation", operation]
        stdout, stderr = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(stdout), contextlib.redirect_stderr(stderr):
            code = main(argv)
        return code, stdout.getvalue(), stderr.getvalue()

    def assert_error(self, code, stdout, stderr, expected_code):
        self.assertEqual(code, 2, stdout)
        self.assertEqual(stdout, "")
        payload = json.loads(stderr)
        self.assertEqual(payload["code"], expected_code)
        self.assertIsInstance(payload["message"], str)
        self.assertTrue(payload["message"])

    def assert_plan(self, code, stdout, stderr):
        self.assertEqual(stderr, "")
        self.assertEqual(code, 0, stderr)
        return json.loads(stdout)

    # -- happy paths ---------------------------------------------------------

    def test_basic_query_with_variable_and_join(self):
        query = """
        query GetUsers($id: ID) {
          users(id: $id) {
            id
            name
            team { id name }
          }
        }
        """
        plan = self.assert_plan(*self.run_cli(query, '{"id": 7}'))
        self.assertEqual(plan["operationType"], "query")
        self.assertEqual(plan["operationName"], "GetUsers")
        self.assertEqual(len(plan["roots"]), 1)
        root = plan["roots"][0]
        self.assertEqual(root["path"], "users")
        self.assertEqual(root["entity"], "users")
        self.assertEqual(root["filter"], {"id": 7})
        self.assertEqual(
            root["fields"],
            ["users.id", "users.name", "users.team.id", "users.team.name"],
        )
        self.assertEqual(
            plan["joins"],
            [{"path": "users.team", "fromEntity": "users", "fromField": "team_id",
              "toEntity": "teams", "toField": "id"}],
        )

    def test_anonymous_operation_and_literal_filter(self):
        plan = self.assert_plan(*self.run_cli('{ users(name: "ada") { id } }'))
        self.assertEqual(plan["operationType"], "query")
        self.assertIsNone(plan["operationName"])
        self.assertEqual(plan["roots"][0]["filter"], {"name": "ada"})
        self.assertEqual(plan["joins"], [])

    def test_mutation(self):
        plan = self.assert_plan(*self.run_cli('mutation { createUser(name: "ada") { id } }'))
        self.assertEqual(plan["operationType"], "mutation")
        self.assertEqual(plan["roots"][0]["entity"], "users")
        self.assertEqual(plan["roots"][0]["filter"], {"name": "ada"})

    def test_aliases_and_multiple_roots(self):
        query = "{ me: user(id: 1) { userId: id } teams { name } }"
        plan = self.assert_plan(*self.run_cli(query))
        self.assertEqual([r["path"] for r in plan["roots"]], ["me", "teams"])
        self.assertEqual(plan["roots"][0]["filter"], {"id": 1})
        self.assertEqual(plan["roots"][0]["fields"], ["me.userId"])
        self.assertEqual(plan["roots"][1]["entity"], "teams")

    def test_fragments_expanded_and_deduplicated(self):
        query = """
        query {
          users { id ...Bits team { id ...TeamBits } }
        }
        fragment Bits on User { id name }
        fragment TeamBits on Team { id name }
        """
        plan = self.assert_plan(*self.run_cli(query))
        root = plan["roots"][0]
        self.assertEqual(
            root["fields"],
            ["users.id", "users.name", "users.team.id", "users.team.name"],
        )
        self.assertEqual(len(plan["joins"]), 1)

    def test_variable_default_used_when_not_provided(self):
        query = "query ($name: String = \"ada\") { users(name: $name) { id } }"
        plan = self.assert_plan(*self.run_cli(query))
        self.assertEqual(plan["roots"][0]["filter"], {"name": "ada"})

    def test_operation_selected_by_name(self):
        query = """
        query A { users { id } }
        query B { teams { name } }
        """
        plan = self.assert_plan(*self.run_cli(query, operation="B"))
        self.assertEqual(plan["operationName"], "B")
        self.assertEqual(plan["roots"][0]["entity"], "teams")

    def test_deep_join_chain(self):
        schema = SCHEMA + """
        extend type Team { league: League @link(local: "league_id", target: "id") }
        extend type Team { league_id: ID }
        type League @entity(name: "leagues", key: "id") { id: ID! title: String }
        """
        query = "{ teams { name league { title } } }"
        plan = self.assert_plan(*self.run_cli(query, schema=schema))
        self.assertEqual(
            plan["joins"],
            [{"path": "teams.league", "fromEntity": "teams", "fromField": "league_id",
              "toEntity": "leagues", "toField": "id"}],
        )
        self.assertEqual(plan["roots"][0]["fields"], ["teams.name", "teams.league.title"])

    # -- operation selection errors -------------------------------------------

    def test_multiple_operations_require_name(self):
        query = "query A { users { id } } query B { teams { id } }"
        self.assert_error(*self.run_cli(query), "InvalidRequest")

    def test_invalid_operation_name(self):
        self.assert_error(
            *self.run_cli("query A { users { id } }", operation="Nope"),
            "InvalidOperation",
        )

    def test_subscription_unsupported(self):
        self.assert_error(
            *self.run_cli("subscription { users { id } }"), "UnsupportedOperation"
        )

    def test_subscription_selected_by_name(self):
        query = "query A { users { id } } subscription S { users { id } }"
        self.assert_error(*self.run_cli(query, operation="S"), "UnsupportedOperation")

    # -- field / entity errors ---------------------------------------------------

    def test_unknown_root_field(self):
        self.assert_error(*self.run_cli("{ nope { id } }"), "UnknownField")

    def test_unknown_nested_field(self):
        self.assert_error(*self.run_cli("{ users { nope } }"), "UnknownField")

    def test_unknown_argument(self):
        self.assert_error(*self.run_cli("{ users(nope: 1) { id } }"), "UnknownField")

    def test_argument_not_an_entity_field(self):
